import {appUxCopy} from '../shared/app-ux-copy.js?v=5.23.0';
import {queueOrders,queueCounts,orderAction,orderHint} from '../shared/app-ux.js?v=5.23.0';
import {connectTeam,consumeStaffLink} from '../shared/team-live.js?v=5.11.0';
import {TEAM_LIVE_COPY} from '../shared/team-live-copy.js?v=5.11.0';
import {staffProjection,staffAction,can} from '../shared/team-state.js?v=5.8.0';
import {teamRead,teamChange,SAMPLE_STORAGE} from '../shared/team-storage.js?v=5.8.0';
import {expansionCopy} from '../shared/expansion-copy.js?v=5.8.0';
import {brandMark,brandLogo} from '../shared/brand.js?v=5.6.0';
import {UI} from '../shared/copy.js?v=5.6.0';
import {CHAT_COPY} from '../shared/conversation-copy.js?v=5.6.0';
import {esc,getLang,setLang,languageOptions} from '../shared/core.js?v=5.6.0';
import {tableLabel,formatBooking,partyLabel,formatMoney} from '../shared/locale.js?v=5.6.0';
const root=document.querySelector('#staff-app'),params=new URLSearchParams(location.search),role=!params.has('store')&&['floor','kitchen'].includes(params.get('role'))?params.get('role'):null;
let id=params.get('member');const key=role?'one-shop-role-preview-'+role:SAMPLE_STORAGE;
const credential=role?null:consumeStaffLink(location.href,localStorage,url=>history.replaceState(null,'',url));
let live=null,previousRevision=null;
let lang=getLang(),tab='ordersView',queueFilter='todo',notice='';const c=()=>({...expansionCopy(lang),...TEAM_LIVE_COPY[lang]}),t=k=>appUxCopy(lang)[k]||c()[k]||CHAT_COPY[lang]?.[k]||UI[lang]?.[k]||k;
function render(){const s=role?teamRead(key):null;if(role)id=s.teamMembers.find(m=>m.role===role)?.id;const v=role?staffProjection(s,id):live?.data; if(v&&!role){id=v.member.id;if(previousRevision&&previousRevision!==v.member.revision)notice=t('accessChanged');previousRevision=v.member.revision;}document.documentElement.lang=lang;document.title=t('demoShop');if(!v){root.innerHTML=`<main class="staff-shell"><div class="staff-invalid">${brandMark('thinking')}<p>${esc(t(role?'revoked':!credential?'credentialsMissing':live?.status||'connecting'))}</p>${credential?`<button class="button" data-live-retry>${esc(t('retry'))}</button>`:''}<small>${esc(t('linkNote'))}</small></div></main>`;return;}const tabs=['ordersView','bookingsView','requestsView','menuView','salesView','settingsView'].filter(p=>can(v.member,p));if(!tabs.includes(tab))tab=tabs[0];root.innerHTML=`<main class="staff-shell"><header class="staff-top">${brandLogo()}<select id="staff-language" aria-label="${esc(t('language'))}">${languageOptions(lang)}</select></header><div class="staff-role">${brandMark(tab==='ordersView'?'order':'greeting',true)}<div><h1>${esc(t(v.member.role))}</h1><p>${esc(v.member.name)} · ${esc(v.shopName)}</p></div></div><p class="staff-note">${esc(t('queueNote'))}</p>${!role?`<span class="staff-live-status">${esc(t('live'))}</span>`:''}<nav class="staff-tabs" aria-label="${esc(t(v.member.role))}">${tabs.map(p=>`<button data-tab="${p}" aria-pressed="${tab===p}">${esc(t(p))}</button>`).join('')}</nav><p class="team-feedback" role="status">${esc(notice)}</p><section class="staff-content">${content(v)}</section><footer class="staff-footer"><details class="staff-demo-help"><summary>${esc(t(role?'localOnly':'live'))}</summary><p>${esc(t(role?'localPreviewNote':'liveNote'))}</p>${role?`<button class="button staff-preview-reset" data-reset>${esc(t('resetPreview'))}</button>`:''}</details><a href="../?lang=${lang}#team-access">${esc(t('book'))}</a></footer></main>`;}
function content(v){const m=v.member;if(tab==='ordersView'){const counts=queueCounts(v.orders,m),readonly=!['ordersAccept','ordersPrepare','ordersServe'].some(p=>can(m,p)),filter=readonly&&queueFilter==='todo'?'all':queueFilter,orders=queueOrders(v.orders,filter,m);return `<div class="queue-switch">${[['todo','todo'],['all','allQueue'],['done','doneQueue']].filter(([key])=>key!=='todo'||!readonly).map(([key,label])=>`<button data-queue="${key}" aria-pressed="${filter===key}">${esc(t(label))}<b>${counts[key]}</b></button>`).join('')}</div>${orders.length?orders.map(o=>{const next=orderAction(o,m);return `<article class="staff-card"><header><h2><small>#${o.number}</small>${esc(o.channel==='online'?t('delivery'):tableLabel(o.table,lang))}</h2><span class="status">${esc(t(o.status))}</span></header><div class="staff-order-items">${o.lines.map(l=>`<p><span>${esc(l.name[lang]||l.name.ko||l.itemId)}</span><b>× ${l.quantity}</b></p>`).join('')}</div>${o.delivery?`<div class="staff-delivery"><small>${esc(t('deliveryAddress'))}</small><p>${esc(o.delivery.address)}</p><small>${esc(t('contact'))}</small><p><a href="tel:${esc(String(o.delivery.phone).replace(/[^+0-9]/g,''))}">${esc(o.delivery.phone)}</a></p></div>`:''}${o.total!==undefined?`<p>${esc(formatMoney(o.total,lang))} · ${esc(t(o.payment))}</p>`:''}${next?`<button class="button primary order-next" data-staff-order="${o.id}" data-next="${next.status}">${esc(t(next.label))}</button>`:`<p class="order-handoff">${esc(t(orderHint(o,m)))}</p>`}</article>`;}).join(''):`<div class="queue-empty">${brandMark('greeting')}<h2>${esc(t('noAction'))}</h2><p>${esc(t(v.member.role==='kitchen'?'waitingFloor':'waitingKitchen'))}</p>${counts.all?`<button class="button" data-queue="all">${esc(t('allQueue'))} · ${counts.all}</button>`:''}</div>`}`;}

 if(tab==='bookingsView')return v.bookings.map(r=>`<article class="staff-card"><header><h2>${esc(formatBooking(r.date,r.time,lang))}</h2><span class="status">${esc(t(r.status==='confirmed'?'bookingConfirmed':r.status))}</span></header><p>${esc(r.name)} · ${esc(partyLabel(r.partySize,lang))}</p>${r.status==='pending'&&can(m,'bookingsManage')?`<button class="button" data-staff-booking="${r.id}">${esc(t('bookingAccept'))}</button>`:''}</article>`).join('')||empty();
 if(tab==='requestsView')return v.requests.map(r=>`<article class="staff-card"><h2>${esc(r.table?tableLabel(r.table,lang):t('online'))}</h2><p>${esc(r.key?t(r.key):r.text||t('requestsView'))}</p></article>`).join('')||empty();
 if(tab==='menuView')return v.items.map(i=>`<article class="staff-card"><header><h2>${esc(i.name[lang]||i.name.ko)}</h2><span class="status">${esc(t(i.available?'available':'soldOut'))}</span></header>${can(m,'menuEdit')?`<button class="button" data-staff-menu="${i.id}" data-available="${!i.available}">${esc(t(i.available?'soldOut':'available'))}</button>`:''}</article>`).join('')||empty();
 if(tab==='salesView')return `<article class="staff-card"><h2>${esc(t('salesView'))}</h2><p>${esc(formatMoney(v.sales,lang))}</p><small>${esc(t(role?'localOnly':'bookBoundary'))}</small></article>`;
 if(tab==='settingsView')return `<article class="staff-card"><h2>${esc(v.settings.name)}</h2>${can(m,'settingsEdit')?`<form id="staff-settings"><label>${esc(t('shopPhone'))}<input name="phone" type="tel" maxlength="30" value="${esc(v.settings.phone)}" required></label><button class="button primary">${esc(t('save'))}</button></form>`:`<p>${esc(t('shopPhone'))} · ${esc(v.settings.phone)}</p>`}</article>`;
 return `<p>${esc(t('noAccess'))}</p>`;}
const empty=()=>`<p>${esc(t('noRecords'))}</p>`;
async function act(action,data){if(live?.busy)return;root.querySelectorAll('button').forEach(b=>b.disabled=true);try{if(role)teamChange(s=>staffAction(s,id,action,data),key);else if(live)await live.mutate('', 'PATCH',{action,data});else throw Error('credentialsMissing');notice=t(action==='order'?data.next:action==='booking'?'bookingConfirmed':'saved');}catch(e){notice=t(e.message);}render();}
root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-live-retry')){live?.invalidate();return;}if(b.dataset.queue){queueFilter=b.dataset.queue;notice='';render();return;}if(b.dataset.tab){tab=b.dataset.tab;notice='';render();}if(b.hasAttribute('data-reset')&&role){localStorage.removeItem(key);notice='';render();}if(b.dataset.staffOrder)act('order',{id:b.dataset.staffOrder,next:b.dataset.next});if(b.dataset.staffBooking)act('booking',{id:b.dataset.staffBooking});if(b.dataset.staffMenu)act('menu',{id:b.dataset.staffMenu,available:b.dataset.available==='true'});});
root.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='staff-settings')act('settings',{phone:new FormData(e.target).get('phone')});});
root.addEventListener('change',e=>{if(e.target.id==='staff-language'){lang=e.target.value;setLang(lang);render();}});
window.addEventListener('storage',e=>{if(role&&e.key===key)render();});if(credential)live=connectTeam({...credential,onchange:()=>render()});render();
